            type: "code",
            title: "statistika.rs",
            code: "#[derive(Debug, Clone)]\nstruct Kitob {\n    nom: String,\n    mavjud: bool,\n}\n\nstruct Kutubxona {\n    kitoblar: Vec<Kitob>,\n}\n\nimpl Kutubxona {\n    fn yangi() -> Self {\n        Self { kitoblar: Vec::new() }\n    }\n\n    fn qosh(&mut self, nom: &str, mavjud: bool) {\n        self.kitoblar.push(Kitob {\n            nom: nom.to_string(),\n            mavjud,\n        });\n    }\n\n    fn eng_uzun(&self) -> Option<&Kitob> {\n        self.kitoblar.iter().max_by_key(|k| k.nom.len())\n    }\n\n    fn mavjud_nomlar(&self) -> Vec<String> {\n        let mut nomlar: Vec<String> = self\n            .kitoblar\n            .iter()\n            .filter(|k| k.mavjud)\n            .map(|k| k.nom.clone())\n            .collect();\n        nomlar.sort();\n        nomlar\n    }\n}\n\nfn main() {\n    let mut kutubxona = Kutubxona::yangi();\n    kutubxona.qosh(\"Rust\", true);\n    kutubxona.qosh(\"Kutubxona tarixi\", true);\n    kutubxona.qosh(\"Cargo\", false);\n    kutubxona.qosh(\"Amaliy Rust\", true);\n\n    match kutubxona.eng_uzun() {\n        Some(kitob) => println!(\"Eng uzun: {}\", kitob.nom),\n        None => println!(\"Kutubxona bo'sh\"),\n    }\n\n    println!(\"Mavjud: {}\", kutubxona.mavjud_nomlar().join(\", \"));\n}",
