            code: "use std::collections::BTreeMap;\nuse std::fmt;\n\n#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]\nenum Janr {\n    Badiiy,\n    Ilmiy,\n    Tarixiy,\n}\n\nimpl Janr {\n    fn nomi(&self) -> &'static str {\n        match self {\n            Janr::Badiiy => \"badiiy\",\n            Janr::Ilmiy => \"ilmiy\",\n            Janr::Tarixiy => \"tarixiy\",\n        }\n    }\n}\n\n#[derive(Debug, Clone)]\nstruct Kitob {\n    id: u32,\n    nom: String,\n    janr: Janr,\n    mavjud: bool,\n}\n\n#[derive(Debug)]\nenum Xato {\n    Topilmadi(u32),\n    Band(u32),\n    AllaqachonMavjud(u32),\n}\n\nimpl fmt::Display for Xato {\n    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {\n        match self {\n            Xato::Topilmadi(id) => write!(f, \"{id}-kitob topilmadi\"),\n            Xato::Band(id) => write!(f, \"{id}-kitob band\"),\n            Xato::AllaqachonMavjud(id) => write!(f, \"{id}-kitob allaqachon mavjud\"),\n        }\n    }\n}\n\nstruct Kutubxona {\n    kitoblar: Vec<Kitob>,\n}\n\nimpl Kutubxona {\n    fn yangi() -> Self {\n        Self { kitoblar: Vec::new() }\n    }\n\n    fn qosh(&mut self, id: u32, nom: &str, janr: Janr) {\n        self.kitoblar.push(Kitob {\n            id,\n            nom: nom.to_string(),\n            janr,\n            mavjud: true,\n        });\n    }\n\n    fn olib_ol(&mut self, id: u32) -> Result<(), Xato> {\n        let kitob = self\n            .kitoblar\n            .iter_mut()\n            .find(|k| k.id == id)\n            .ok_or(Xato::Topilmadi(id))?;\n        if !kitob.mavjud {\n            return Err(Xato::Band(id));\n        }\n        kitob.mavjud = false;\n        Ok(())\n    }\n\n    fn qaytar(&mut self, id: u32) -> Result<(), Xato> {\n        let kitob = self\n            .kitoblar\n            .iter_mut()\n            .find(|k| k.id == id)\n            .ok_or(Xato::Topilmadi(id))?;\n        if kitob.mavjud {\n            return Err(Xato::AllaqachonMavjud(id));\n        }\n        kitob.mavjud = true;\n        Ok(())\n    }\n\n    fn qidir(&self, soz: &str) -> Vec<&Kitob> {\n        let soz = soz.to_lowercase();\n        let mut topilgan: Vec<&Kitob> = self\n            .kitoblar\n            .iter()\n            .filter(|k| k.nom.to_lowercase().contains(&soz))\n            .collect();\n        topilgan.sort_by(|a, b| a.nom.cmp(&b.nom));\n        topilgan\n    }\n\n    fn hisobot(&self) -> BTreeMap<&'static str, usize> {\n        let mut hisob = BTreeMap::new();\n        for kitob in &self.kitoblar {\n            *hisob.entry(kitob.janr.nomi()).or_insert(0) += 1;\n        }\n        hisob\n    }\n}\n\nfn main() {\n    let mut kutubxona = Kutubxona::yangi();\n    kutubxona.qosh(1, \"Rust asoslari\", Janr::Ilmiy);\n    kutubxona.qosh(2, \"Cargo qollanma\", Janr::Ilmiy);\n    kutubxona.qosh(3, \"O'tkan kunlar\", Janr::Badiiy);\n    kutubxona.qosh(4, \"Rust tarixi\", Janr::Tarixiy);\n\n    kutubxona.olib_ol(2).unwrap();\n    match kutubxona.olib_ol(2) {\n        Ok(()) => println!(\"2-kitob olindi\"),\n        Err(e) => println!(\"Xato: {e}\"),\n    }\n    kutubxona.qaytar(2).unwrap();\n    println!(\"2-kitob qaytarildi\");\n\n    for kitob in kutubxona.qidir(\"rust\") {\n        println!(\"{} ({})\", kitob.nom, kitob.janr.nomi());\n    }\n\n    for (janr, soni) in kutubxona.hisobot() {\n        println!(\"{janr}: {soni}\");\n    }\n\n    let mavjud = kutubxona.kitoblar.iter().filter(|k| k.mavjud).count();\n    println!(\"Mavjud: {mavjud}/{}\", kutubxona.kitoblar.len());\n}",
